import pandas as pd
import numpy as np

# load computed series from previous script quickly
from statsmodels.tsa.filters.hp_filter import hpfilter

pce = pd.read_excel('/root/ERP-2025-table10.xls', sheet_name=0, header=None)
pfi = pd.read_excel('/root/ERP-2025-table12.xls', sheet_name=0, header=None)

def extract_series(df, year_start=1973, year_end=2024, value_col=1):
    annual = {}
    for idx, row in df.iterrows():
        v = row[0]
        if isinstance(v, (int, float)) and not pd.isna(v):
            year = int(v)
            if year_start <= year <= year_end:
                annual[year] = row[value_col]
        elif isinstance(v, str):
            if v.strip().endswith('.') and v.strip().replace('.', '').isdigit():
                year = int(v.strip().replace('.', ''))
                if year_start <= year <= year_end:
                    annual[year] = row[value_col]
    if year_end not in annual:
        q_vals = []
        for idx, row in df.iterrows():
            v = row[0]
            if isinstance(v, str) and v.strip().startswith(f"{year_end}:"):
                val = row[value_col]
                if not pd.isna(val):
                    q_vals.append(val)
        if q_vals:
            annual[year_end] = float(np.mean(q_vals))
    years = list(range(year_start, year_end + 1))
    series = pd.Series([annual.get(y, np.nan) for y in years], index=years, dtype='float64')
    return series

pce_nom = extract_series(pce)
pfi_nom = extract_series(pfi)
print('PCE missing years', pce_nom[pce_nom.isna()].index.tolist())
print('PFI missing years', pfi_nom[pfi_nom.isna()].index.tolist())
print('2024 PCE', pce_nom.loc[2024])
print('2024 PFI', pfi_nom.loc[2024])
